@dataclass(frozen=True)
class PostgresRef:
    """A CNPG Cluster as clients address it: CNPG names the primary's Service `<name>-rw` and labels
    every instance Pod `cnpg.io/cluster: <name>`."""

    name: str
    namespace: str
    app_secret: SecretRef

